public sealed class CommittedNumericUpDown:NumericUpDown {
 decimal committed;
 // Value validates and autocorrects the text being typed; Committed does not until the field is left.
 public decimal Committed {get{return UserEdit?committed:Value;}}
 protected override void OnEnter(EventArgs e){committed=Value;base.OnEnter(e);}
 protected override void OnValueChanged(EventArgs e){committed=Value;base.OnValueChanged(e);}
}
